\section{Quota ladders}\label{sec:ladder}

Let $\iota$ be a finite set of seeds, $n=|\iota|$, and $K:\iota\to\mathbb{N}$ the knee assignment:
$K(i)$ is the least budget at which seed $i$ clears the bar.

\begin{definition}[Pass set]
For a budget $b$, $\Pass_K(b)=\{i\in\iota: K(i)\le b\}$.
\end{definition}

\begin{definition}[Quota ladder]
For $m\in\mathbb{N}$, the $m$-th rung is
$Q_K(m)=\min\{\,b : |\Pass_K(b)|\ge m\,\}$, the least budget at which at least $m$ seeds clear
the bar.
\end{definition}

$Q_K$ is non-decreasing in $m$, $Q_K(0)=0$, and $|\Pass_K(Q_K(m))|\ge m$ for $m\le n$.

\begin{proposition}[Rungs are order statistics]
For $1\le m\le n$, $Q_K(m)$ is the $m$-th smallest value of $K$. In particular $Q_K(1)$ is the best
case, $Q_K(n)$ the guarantee, and for $n=2r+1$ the rung $Q_K(r+1)$ is the median.
\end{proposition}

\begin{proof}[Proof sketch]
$|\Pass_K(b)|\ge m$ holds iff $b$ is at least the $m$-th smallest value of $K$; take the least
such $b$.
\end{proof}

\section{The rung distribution function and the parity law}\label{sec:parity}

\begin{definition}
The \emph{rung distribution function} is
\[
R_n(m,p)\;=\;\sum_{j=m}^{n}\binom{n}{j}p^{\,j}(1-p)^{\,n-j},\qquad 0\le p\le 1 .
\]
\end{definition}

Under the model ``each seed clears the fixed bar independently with probability $p$'', $R_n(m,p)$
is the probability that rung $m$ sits at or below that budget.

\begin{proposition}[Basic structure]\label{prop:basic}
For $0\le p\le1$:
\begin{enumerate}
\item $R_n(0,p)=1$, and $R_n(m,p)=0$ for $m>n$;
\item $R_n(\cdot,p)$ is antitone in $m$; $R_n(m,\cdot)$ is monotone in $p$, strictly for
$1\le m\le n$ and $0<p<q<1$;
\item $R_{n+1}(m+1,p)=p\,R_n(m,p)+(1-p)\,R_n(m+1,p)$;
\item for $m\le n$, $R_n(m,p)-R_n(m+1,p)=\binom{n}{m}p^{m}(1-p)^{n-m}$.
\end{enumerate}
\end{proposition}

\begin{proof}[Proof sketch]
(1) is the binomial theorem for $(p+(1-p))^n$. (2) antitonicity is a sum over a smaller index set
of non-negative terms; monotonicity in $p$ is an induction on $n$ through (3), strictness from (4).
(3) conditions on the last seed and uses Pascal's rule after an index shift. (4) isolates the
$j=m$ term.
\end{proof}

\begin{definition}
Rung $m$ of an $n$-seed ensemble is \emph{calibrated} if $R_n(m,\tfrac12)=\tfrac12$.
\end{definition}

At $p=1/2$, $R_n(m,\tfrac12)=T(n,m)/2^{n}$ with $T(n,m)=\sum_{j\ge m}\binom{n}{j}$.

\begin{lemma}[Reflection]\label{lem:refl}
For $m\le n+1$, $T(n,m)+T(n,n+1-m)=2^{\,n}$, and $T(n,\cdot)$ is strictly decreasing on
$\{0,\dots,n+1\}$.
\end{lemma}

\begin{proof}[Proof sketch]
$j\mapsto n-j$ maps the tail $\{j\ge m\}$ onto the head $\{j\le n-m\}$ and preserves binomial
coefficients, so the two counts partition $2^n$; each quota step removes a positive coefficient.
\end{proof}

\begin{theorem}[Parity law of calibration]\label{thm:parity}
For $m\le n+1$,
\[
R_n\!\left(m,\tfrac12\right)=\tfrac12 \iff 2m=n+1 .
\]
Hence an $n$-seed ensemble has a calibrated rung iff $n$ is odd; for $n=2r+1$ it is unique, namely
the median $m=r+1$; for even $n$ there is none.
\end{theorem}

\begin{proof}[Proof sketch]
$R_n(m,\tfrac12)=\tfrac12$ means $T(n,m)=T(n,n+1-m)$ by Lemma~\ref{lem:refl}; strict monotonicity
forces $m=n+1-m$. Conversely $2m=n+1$ makes the reflection identity read $2T(n,m)=2^{n}$.
\end{proof}

\begin{definition}
$\displaystyle \delta_r=\frac{1}{2^{2r+1}}\binom{2r}{r}$.
\end{definition}

\begin{theorem}[Even central rungs]\label{thm:evencentral}
For every $r$,
\[
R_{2r}\!\left(r,\tfrac12\right)=\tfrac12+\delta_r,\qquad
R_{2r}\!\left(r+1,\tfrac12\right)=\tfrac12-\delta_r,\qquad \delta_r>0,
\]
so the two central rungs of an even ensemble average to exactly $\tfrac12$.
\end{theorem}

\begin{proof}[Proof sketch]
The two rungs differ by the single central term $\binom{2r}{r}2^{-2r}$
(Proposition~\ref{prop:basic}(4) at $p=1/2$) and sum to $1$ by reflection; solve.
\end{proof}

\begin{remark}
Theorem~\ref{thm:evencentral} identifies the textbook convention ``the median of an even sample is
the mean of the two middle order statistics'' as the exact repair of a measurable parity defect,
not an arbitrary tie-break.
\end{remark}

\begin{theorem}[Defect decay]\label{thm:sandwich}
$\delta_{r+1}<\delta_r$ and $\delta_r\to0$. Moreover for all $r$
\[
16^{\,r}\le\binom{2r}{r}^{2}(4r+1),\qquad \binom{2r}{r}^{2}(3r+1)\le 16^{\,r},
\]
hence
\[
\frac{4^{\,r}}{\sqrt{4r+1}}\le\binom{2r}{r}\le\frac{4^{\,r}}{\sqrt{3r+1}},\qquad
\frac{1}{2\sqrt{4r+1}}\le\delta_r\le\frac{1}{2\sqrt{3r+1}} .
\]
In particular $\delta_r\sqrt r\in[\,1/(2\sqrt5),\,1/(2\sqrt3)\,]$ for $r\ge1$ and
$\sum_r \delta_r=\infty$.
\end{theorem}

\begin{proof}[Proof sketch]
Both inequalities are inductions through $(r+1)\binom{2r+2}{r+1}=2(2r+1)\binom{2r}{r}$; in the lower
bound the induction slack is exactly $1$. Dividing by $2^{2r+1}$ transfers the sandwich to
$\delta_r$; $\delta_r\ge 1/(4(r+1))$ gives divergence.
\end{proof}

\begin{theorem}[Exact asymptotic constant]
$\displaystyle \lim_{r\to\infty}\delta_r\sqrt r=\frac{1}{2\sqrt\pi}=0.28209\ldots$, equivalently
$\binom{2r}{r}\sqrt r/4^{\,r}\to 1/\sqrt\pi$.
\end{theorem}

\begin{proof}[Proof sketch]
With $s_r=r!/(\sqrt r\,(r/e)^r)$ the Stirling sequence, an algebraic cancellation of factorials
gives $s_{2r}/s_r^{2}=\binom{2r}{r}\sqrt r/4^{\,r}$ for $r\ge1$; since $s_r\to\sqrt{2\pi}$ the limit
is $\sqrt{2\pi}/(2\pi)=1/\sqrt\pi$.
\end{proof}

\begin{remark}
Consistency of the last two theorems is exactly the statement $3\le\pi\le5$, read off a ladder of
ensembles rather than a circle.
\end{remark}

\section{Robustness: the exact breakdown number}\label{sec:robust}

Let $K,K':\iota\to\mathbb{N}$ agree outside a set $S$ of \emph{corrupted} seeds.

\begin{theorem}[Two-sided bracket]\label{thm:bracket}
If $|S|\le c\le m-1$ and $m+c\le n$, then
$Q_K(m-c)\le Q_{K'}(m)\le Q_K(m+c)$.
\end{theorem}

\begin{proof}[Proof sketch]
If $K,K'$ agree off $S$ then $Q_{K'}(m)\le Q_K(m+|S|)$, because at a budget where $m+|S|$ seeds pass
under $K$, at least $m$ of them lie outside $S$ and hence pass under $K'$. Exchanging $K$ and $K'$
and using monotonicity of $Q_K$ gives the lower bound.
\end{proof}

\begin{definition}
The \emph{breakdown number} of the $m$-th rung of an $n$-seed ensemble is
$\beta(n,m)=\min(m-1,\,n-m)$.
\end{definition}

\begin{corollary}
If $1\le m\le n$ and $|S|\le\beta(n,m)$ then $Q_K(1)\le Q_{K'}(m)\le Q_K(n)$: the corrupted reading
remains inside the clean ensemble's own range.
\end{corollary}

\begin{theorem}[Upward breakdown]\label{thm:up}
Let $m\le n$ and $|S|>n-m$. For every bound $B$ there is $K'$ agreeing with $K$ off $S$ with
$Q_{K'}(m)\ge B$.
\end{theorem}

\begin{proof}[Proof sketch]
Put $K'=B$ on $S$ and $K$ elsewhere. If $Q_{K'}(m)<B$ then $\Pass_{K'}(Q_{K'}(m))$ misses $S$
entirely, hence has at most $n-|S|<m$ elements, contradicting the defining property of the rung.
\end{proof}

\begin{theorem}[Downward breakdown]
If $|S|\ge m$ there is $K'$ agreeing with $K$ off $S$ with $Q_{K'}(m)=0$.
\end{theorem}

\begin{proof}[Proof sketch]
Put $K'=0$ on $S$; then $S\subseteq\Pass_{K'}(0)$ and the quota is met at budget $0$.
\end{proof}

\begin{corollary}[Exactness]
The $m$-th rung tolerates exactly $\min(m-1,n-m)$ corrupted seeds. In particular the guarantee rung
$m=n$ and the best-case rung $m=1$ both have breakdown number $0$: a single corrupted seed makes
either reading arbitrary.
\end{corollary}

\begin{theorem}[Contamination curve]\label{thm:curve}
For $1\le m\le n$ and $c\le\beta(n,m)$, the readings of rung $m$ achievable by corrupting at most
$c$ seeds are exactly the clean rungs in $[\,Q_K(m-c),\,Q_K(m+c)\,]$, both endpoints attained.
\end{theorem}

\begin{proof}[Proof sketch]
Containment is Theorem~\ref{thm:bracket}. Attainment: corrupt the $c$ largest knees upward for the
right endpoint, the $c$ smallest downward for the left.
\end{proof}

Thus the maximal adversarial bias at level $c$ equals the clean spread $Q_K(m+c)-Q_K(m-c)$, and
$\beta(n,m)$ is the level at which that spread ceases to be finite.

\section{The dichotomy}\label{sec:dichotomy}

\begin{lemma}\label{lem:oddmax}
For $n=2r+1$ and $1\le m\le n$: $\beta(n,m)\le r$, with equality iff $m=r+1$.
\end{lemma}

\begin{proof}[Proof sketch]
The two arguments of the minimum sum to $2r$; equality requires both to be at least $r$.
\end{proof}

\begin{theorem}[Calibration--Robustness Dichotomy]\label{thm:main}
Let $n=2r+1$ and $1\le m\le n$. Then
\[
R_n\!\left(m,\tfrac12\right)=\tfrac12\quad\Longleftrightarrow\quad \beta(n,m)=r .
\]
A rung is calibrated on coin-flip seeds if and only if it is maximally robust to corrupted seeds.
\end{theorem}

\begin{proof}[Proof sketch]
Theorem~\ref{thm:parity} makes the left side equivalent to $m=r+1$; Lemma~\ref{lem:oddmax} makes the
right side equivalent to the same.
\end{proof}

The content is that the two sides come from disjoint premises: a symmetry of binomial coefficients
on one side, a counting bound on adversarial corruptions on the other. ``Read the median'' is a
theorem, not a convention.

\begin{theorem}[Even ensembles fail on both sides]\label{thm:even}
Let $n=2r$ with $r\ge1$. Then $\beta(2r,m)\le r-1$ for all $1\le m\le 2r$; the maximum $r-1$ is
attained by the two distinct rungs $m=r$ and $m=r+1$; and no rung is calibrated.
\end{theorem}

\begin{proof}[Proof sketch]
Arithmetic on $\min(m-1,2r-m)$, plus Theorem~\ref{thm:parity}.
\end{proof}

Parity is a single obstruction to a canonical centre, visible simultaneously in the probability and
in the robustness.

\section{How many seeds certify a centre?}\label{sec:condorcet}

\begin{theorem}[Condorcet monotonicity]\label{thm:condorcet}
For $1/2\le p\le1$, $R_{2r+1}(r+1,p)$ is non-decreasing in $r$, strictly increasing for $0<2p-1<1$;
for $p<1/2$ it is strictly decreasing. The exact step is
\[
R_{2r+3}(r+2,p)-R_{2r+1}(r+1,p)=\binom{2r+1}{r}\bigl(p(1-p)\bigr)^{r+1}(2p-1).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Apply the Pascal recursion twice and cancel; the sign is that of $2p-1$.
\end{proof}

\begin{theorem}[Geometric rate]\label{thm:rate}
For $1/2\le p\le1$: $1-R_{2r+1}(r+1,p)\le 2(1-p)\bigl(4p(1-p)\bigr)^{r}$.
\end{theorem}

\begin{proof}[Proof sketch]
Telescope the exact step to infinity, bounding $\binom{2r+1}{r}\le4^{r}$, and sum the geometric
series in $4p(1-p)<1$.
\end{proof}

\begin{theorem}[Sharpened rate]\label{thm:sharp}
For $1/2<p\le1$,
\[
1-R_{2r+1}(r+1,p)\le\frac{\binom{2r+1}{r}\bigl(p(1-p)\bigr)^{r+1}}{2p-1}
\le \frac{2p(1-p)\bigl(4p(1-p)\bigr)^{r}}{(2p-1)\sqrt{3r+4}},
\]
the second inequality using the central binomial sandwich of Theorem~\ref{thm:sandwich}.
\end{theorem}

\begin{theorem}[Exact crossing at $p=2/3$]
$1-R_{47}(24,\tfrac23)\le\tfrac1{100}$ while $1-R_{45}(23,\tfrac23)>\tfrac1{100}$. Hence the median
rung at per-seed frequency $2/3$ is certified to within $1\%$ iff the ensemble has at least $47$
seeds.
\end{theorem}

\begin{theorem}[No sharp route to $47$]
Any bound dominating the sharpened rate of Theorem~\ref{thm:sharp} fails to certify $1\%$ at $47$
seeds, since the sharpened rate itself exceeds $1/100$ there. The sharpened route certifies at $49$
seeds; the crude rate of Theorem~\ref{thm:rate} needs $73$.
\end{theorem}

\begin{proposition}[Where the measurement stands]
$R_3(2,p)=3p^{2}-2p^{3}$, so at $p=2/3$ the three-seed median rung has $R_3(2,\tfrac23)=20/27$ and
miss probability $7/27\approx25.9\%$.
\end{proposition}

A three-seed centre is a point estimate with a one-in-four failure probability under its own
frequency model --- not a certified centre.

\section{Is the median also the narrowest reading?}\label{sec:window}

By Theorem~\ref{thm:curve} the deployment-relevant uncertainty of rung $m$ at level $c$ is the
window width $W(m,c)=Q(m+c)-Q(m-c)$.

\begin{theorem}[Refutation in general]
The five-seed sample $\{0,0,0,10,20\}$ has ladder $Q=(0,0,0,10,20)$, so $W(3,1)=10$ while
$W(2,1)=0$: the median window is strictly wider than an off-centre one.
\end{theorem}

\begin{definition}
Let $g(j)=Q(j)-Q(j-1)$ and $\cd(n,j)=|n-2j|$. The ladder is \emph{centre-minimal} if
$\cd(n,j)\le\cd(n,k)$ implies $g(j)\le g(k)$: gaps nearer the middle are smaller, as for order
statistics of a unimodal law.
\end{definition}

\begin{theorem}[Minimality under centre-minimality]
If the ladder of a $(2r+1)$-seed ensemble is monotone and centre-minimal, then for every radius
$c\le r$ the median window is narrowest: $W(r+1,c)\le W(m,c)$ for all admissible $m$.
\end{theorem}

\begin{proof}[Proof sketch]
An exact step criterion --- moving a window outward changes its width by the incoming gap minus the
outgoing gap --- drives a two-sided induction; centre-minimality makes every outward step
non-improving on both sides.
\end{proof}

\begin{proposition}
For the three-seed sample $\{160,224,256\}$ the gaps $g(2)=64$ and $g(3)=32$ are equidistant from
the centre yet unequal, so centre-minimality holds only vacuously; correspondingly $\beta(3,2)=1$
while $\beta(3,1)=\beta(3,3)=0$, so at three seeds the median is the only rung with a contamination
window at all.
\end{proposition}

\section{Application: the fourth seed, the fifth seed, and the median law}\label{sec:application}

\subsection{The three-seed reading}

For $K=\{160,224,256\}$ the ladder is $Q(1)=160$, $Q(2)=224$, $Q(3)=256$, and
$Q(2)=224=\tfrac78\cdot\tfrac{4\cdot2048}{32}$. By Theorem~\ref{thm:main} the rung $m=2$ is the
unique calibrated, maximally robust rung ($\beta(3,2)=1$, $R_3(2,\tfrac12)=\tfrac12$); by
Theorem~\ref{thm:curve} its contamination curve at $c=1$ is exactly $[160,256]$, a maximal bias of
$-64/+32$. The guarantee rung has $\beta(3,3)=0$ and can be pushed above any bound by one bad seed.

\subsection{What a fourth seed does}

With $x$ the fourth knee, the four-seed reading (mean of the two middle order statistics of
$\{160,224,256,x\}$) is
\[
\rho(x)=\begin{cases}
192,&x\le160,\\[2pt]
\dfrac{x+224}{2},&160\le x\le224,\\[4pt]
\dfrac{224+x}{2},&224\le x\le256,\\[4pt]
240,&x\ge256,
\end{cases}
\qquad \bias(x)=|\rho(x)-224| .
\]

\begin{theorem}[A fourth seed confirms but cannot calibrate]
\begin{enumerate}
\item $\rho$ is monotone with range $[192,240]$ and $\bias(x)\le32$ always;
\item $\bias(x)=0$ iff $x=224$; otherwise the four-seed reading is strictly worse than the exact
three-seed median;
\item $\bias(x)=32$ iff $x\le160$, and $\bias(x)\le16$ iff $x\ge192$; the bias is strictly
decreasing on $[160,224]$ and strictly increasing on $[224,256]$;
\item no rung of a four-seed ensemble is calibrated, the central defect being
$\delta_2=\binom{4}{2}/2^{5}=3/16$, so the central rungs read $0.6875$ and $0.3125$;
\item $\beta(4,2)=\beta(4,3)=1$, no better than $\beta(3,2)=1$, and no four-seed rung exceeds $1$.
\end{enumerate}
\end{theorem}

\begin{theorem}[The fifth seed restores both]
$\beta(5,3)=2>1$ and $R_5(3,\tfrac12)=\tfrac12$.
\end{theorem}

A fourth run at the same cell therefore purchases neither robustness nor calibration; the correct
increment for the centre is two seeds. (A fourth run remains diagnostic for the \emph{low tail},
but that is a tail experiment, not a centre experiment.)

